package matteroverdrive.menu;import matteroverdrive.blockentity.StarMapBlockEntity;import matteroverdrive.registry.*;import net.minecraft.core.BlockPos;import net.minecraft.network.FriendlyByteBuf;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.*;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.block.entity.BlockEntity;
public class StarMapMenu extends AbstractContainerMenu{private final StarMapBlockEntity map;private final ContainerData data;public StarMapMenu(int id,Inventory inv,FriendlyByteBuf b){this(id,inv,find(inv,b.readBlockPos()),new SimpleContainerData(2));}public StarMapMenu(int id,Inventory inv,StarMapBlockEntity map){this(id,inv,map,map.data());}private StarMapMenu(int id,Inventory inv,StarMapBlockEntity map,ContainerData d){super(ModMenus.STAR_MAP.get(),id);this.map=map;data=d;for(int r=0;r<3;r++)for(int c=0;c<9;c++)addSlot(new Slot(inv,c+r*9+9,8+c*18,78+r*18));for(int c=0;c<9;c++)addSlot(new Slot(inv,c,8+c*18,136));addDataSlots(d);}private static StarMapBlockEntity find(Inventory i,BlockPos p){BlockEntity b=i.player.level().getBlockEntity(p);return b instanceof StarMapBlockEntity m?m:new StarMapBlockEntity(p,ModBlocks.get("star_map").get().defaultBlockState());}@Override public boolean stillValid(Player p){return stillValid(ContainerLevelAccess.create(p.level(),map.getBlockPos()),p,ModBlocks.get("star_map").get());}@Override public ItemStack quickMoveStack(Player p,int i){return ItemStack.EMPTY;}public int active(){return data.get(0);}public int complete(){return data.get(1);}}